const EBOOKS=[{"id": "cuidar", "nome": "Cuidar Sem Medo", "curto": "Cuidador de Idosos", "horas": 12, "c1": "#06465A", "c2": "#F59A2C", "capa": "capas/cuidar.jpg", "modulos": [{"t": "Entendendo o Envelhecimento", "min": 55, "resumo": ["Envelhecer é um processo natural, gradual e universal, não uma doença.", "Cada pessoa envelhece de um jeito: a idade no documento não diz tudo.", "Envelhecimento ativo = manter capacidade funcional, independência e propósito."], "qs": [{"q": "Envelhecer é, segundo o e-book:", "o": ["Uma doença", "Um processo natural, gradual e universal", "Sinal de incapacidade", "Um problema só do corpo"], "a": 1}, {"q": "Para a OMS, envelhecer bem é:", "o": ["Não ter nenhuma doença", "Viver só em casa", "Manter a capacidade funcional ao longo da vida", "Evitar o contato social"], "a": 2}, {"q": "Dois idosos com a mesma idade:", "o": ["Podem ter necessidades completamente diferentes", "Têm sempre as mesmas necessidades", "Reagem igual aos remédios", "Dormem do mesmo jeito"], "a": 0}, {"q": "Qual item NÃO é pilar do envelhecimento saudável?", "o": ["Alimentação equilibrada", "Estímulo cognitivo e social", "Repouso absoluto, sem atividade física", "Prevenção de quedas"], "a": 2}, {"q": "O grupo etário que mais cresce no Brasil é o de:", "o": ["60 a 64 anos", "65 a 69 anos", "70 a 74 anos", "80 anos ou mais"], "a": 3}, {"q": "O envelhecimento da população brasileira acontece:", "o": ["Mais devagar que na França", "Mais rápido que na França", "No mesmo ritmo da França", "Sem relação com a França"], "a": 1}, {"q": "O corpo do idoso, em relação aos remédios:", "o": ["Reage igual ao do adulto jovem", "Não absorve nenhum remédio", "Processa de forma diferente e mais lenta", "Dispensa a dose"], "a": 2}, {"q": "Chamar uma queixa do idoso de 'frescura' ou 'coisa da idade' é:", "o": ["Um erro que atrapalha o cuidado", "A conduta recomendada", "Uma forma de respeito", "Irrelevante"], "a": 0}, {"q": "A expectativa média de vida no Brasil já passa de:", "o": ["66 anos", "76 anos", "86 anos", "96 anos"], "a": 1}, {"q": "A atividade física do idoso deve ser:", "o": ["Proibida", "Só intensa", "Só em academia", "Regular e adaptada às limitações"], "a": 3}], "caso": {"texto": "Seu Antônio, 78 anos, e seu vizinho Seu Pedro, também 78, são tratados pelos filhos do mesmo jeito: 'na idade deles todo mundo fica assim'. Seu Antônio caminha todo dia e cozinha; Seu Pedro precisa de ajuda para se vestir.", "perguntas": ["Por que tratar os dois igual é um erro?", "Que diferenças você observaria para planejar o cuidado de cada um?", "Que frase você usaria para explicar isso aos filhos?"]}, "ativ": {"texto": "Observe um idoso conhecido (ou imagine um). Preencha uma ficha: 3 coisas que ele faz sozinho, 3 em que precisa de ajuda e 3 atividades que ele gosta. Depois escreva 2 ações para sustentar o que ele ainda faz bem.", "tempo": "40 min"}}, {"t": "Seus Direitos (e os do Idoso): o Estatuto do Idoso na Prática", "min": 55, "resumo": ["Estatuto do Idoso (Lei 10.741/2003): prioridade, saúde pelo SUS, remédios, BPC, transporte e proteção.", "Conhecer direitos é ferramenta de trabalho do cuidador.", "Denúncias: CRAS/CREAS e Disque 100."], "qs": [{"q": "O Estatuto do Idoso é a lei:", "o": ["10.741/2003", "8.080/1990", "12.345/2010", "9.999/1999"], "a": 0}, {"q": "A partir de que idade há atendimento prioritário?", "o": ["50 anos", "55 anos", "60 anos", "70 anos"], "a": 2}, {"q": "O BPC é um benefício de:", "o": ["Dois salários mínimos", "Um salário mínimo mensal para idosos de 65+ sem meios de subsistência", "Aposentadoria por tempo de serviço", "Auxílio só para quem trabalhou"], "a": 1}, {"q": "Medicamentos essenciais podem ser obtidos pelo:", "o": ["Apenas plano de saúde", "Só farmácias particulares", "SUS e Farmácia Popular", "Apenas hospitais privados"], "a": 2}, {"q": "Onde denunciar negligência ou abuso?", "o": ["Somente na delegacia", "CRAS/CREAS e Disque 100", "Apenas em redes sociais", "Não há onde denunciar"], "a": 1}, {"q": "No transporte interestadual, quem se enquadra tem:", "o": ["Gratuidade total", "Nenhum benefício", "Desconto de 50%", "Desconto de 5%"], "a": 2}, {"q": "Profissionais de saúde e assistência social, diante de suspeita de violência contra o idoso:", "o": ["Devem esperar a família decidir", "São obrigados a notificar", "Não devem agir", "Só notificam se o idoso pedir"], "a": 1}, {"q": "Os Conselhos da Pessoa Idosa:", "o": ["Existem só em nível federal", "Fiscalizam o cumprimento da lei em níveis nacional, estadual e municipal", "Cobram taxas", "Não têm função"], "a": 1}, {"q": "A Caderneta da Pessoa Idosa serve para:", "o": ["Guardar documentos pessoais", "Registrar o acompanhamento de saúde", "Pedir aposentadoria", "Comprar remédios"], "a": 1}, {"q": "A frase 'Conhecer os direitos também é cuidar' significa que:", "o": ["Direitos são só para advogados", "O cuidador também 'advoga' pelos direitos de quem cuida", "Direitos não importam no dia a dia", "O idoso nunca precisa de lei"], "a": 1}], "caso": {"texto": "Dona Lúcia, 82 anos, mora com a neta, tem pressão alta e diabetes, gasta quase toda a aposentadoria em remédios e nunca foi cadastrada na unidade de saúde do bairro.", "perguntas": ["Que direitos poderiam aliviar o orçamento dela?", "Quais seriam seus 3 primeiros passos como cuidador?", "A quem você pediria orientação?"]}, "ativ": {"texto": "Monte um 'Painel de Direitos' de uma página para um idoso: UBS do bairro, endereço do CRAS, telefone do Disque 100, lista de remédios que podem ser retirados pelo SUS/Farmácia Popular (pesquise na farmácia mais próxima).", "tempo": "45 min"}}, {"t": "Cidadania e Ética: o Papel Transformador do Cuidador", "min": 55, "resumo": ["Idoso tem direito a voz, autonomia e dignidade.", "Infantilização e etarismo são formas sutis de desrespeito.", "Ética: sigilo, respeito e escuta ativa."], "qs": [{"q": "Tratar o idoso como incapaz de decidir sobre a própria vida chama-se:", "o": ["Cuidado ativo", "Infantilização", "Autonomia", "Escuta ativa"], "a": 1}, {"q": "Respeitar a cidadania do idoso inclui:", "o": ["Decidir tudo por ele", "Permitir que escolha o que vestir, comer e quando descansar", "Ignorar seus desejos", "Falar só com a família"], "a": 1}, {"q": "Escuta ativa é:", "o": ["Responder sem ouvir", "Validar sentimentos e desejos, mesmo discordando", "Mudar de assunto", "Corrigir o idoso o tempo todo"], "a": 1}, {"q": "Etarismo é:", "o": ["Preconceito por causa da idade", "Respeito pela idade", "Um tipo de remédio", "Uma lei"], "a": 0}, {"q": "Combater o etarismo é:", "o": ["Rir de comentários sobre idade", "Questionar atitudes que diminuem o idoso por causa da idade", "Evitar o assunto", "Concordar sempre"], "a": 1}, {"q": "O idoso deve ser, nas decisões da família:", "o": ["Apenas informado depois", "Consultado sobre o que diz respeito a ele", "Deixado de fora", "Representado por vizinhos"], "a": 1}, {"q": "Sigilo profissional do cuidador significa:", "o": ["Comentar a vida do idoso com amigos", "Manter absoluto segredo sobre a vida do idoso e da família", "Postar nas redes", "Contar à vizinhança"], "a": 1}, {"q": "Tratar o idoso 'de acordo com a história de vida dele' é:", "o": ["Valorizar quem ele foi e é", "Ignorar o passado", "Tratá-lo como criança", "Só olhar a doença"], "a": 0}, {"q": "Infantilizar o idoso é um erro mesmo quando:", "o": ["Vem de má intenção", "Vem de boa intenção", "Nunca é erro", "Só acontece em hospitais"], "a": 1}, {"q": "A ética valoriza a reputação do cuidador porque:", "o": ["Reputação se constrói devagar e se perde rápido", "Reputação não importa", "Só vale o certificado", "A família não observa"], "a": 0}], "caso": {"texto": "A filha de Seu Hélio, 80 anos, decide sozinha vender o carro dele 'porque ele não dirige mais' e fala com ele usando diminutivos: 'o vovozinho vai tomar o remedinho'. Ele fica calado e triste.", "perguntas": ["Que atitudes desrespeitam a cidadania do Seu Hélio?", "Como você abordaria a família com gentileza?", "Que alternativa respeita a autonomia dele?"]}, "ativ": {"texto": "Escreva um 'Código de Conduta do Cuidador' com 8 regras (sigilo, respeito, pontualidade, autonomia etc.), cada uma com um exemplo prático. Assine e guarde.", "tempo": "40 min"}}, {"t": "Como Avaliar e Identificar Sinais de Alerta", "min": 55, "resumo": ["Observe: alimentação, visão/audição, mobilidade, ABVD, AIVD, cognição, humor, continência, vacinação.", "Mudança em mais de uma área = procurar o médico.", "Depressão é comum e subdiagnosticada."], "qs": [{"q": "ABVD são:", "o": ["Atividades básicas como banho, vestir-se, ir ao banheiro e comer", "Atividades de lazer", "Atividades bancárias", "Atividades de trabalho"], "a": 0}, {"q": "AIVD incluem:", "o": ["Escovar os dentes", "Dormir", "Fazer compras, usar transporte, cuidar de remédios e finanças", "Tomar banho"], "a": 2}, {"q": "Perder peso sem explicação é um:", "o": ["Sinal de saúde perfeita", "Detalhe sem importância", "Efeito da idade, sempre", "Sinal de alerta"], "a": 3}, {"q": "Perder-se em lugares conhecidos e repetir perguntas pode indicar:", "o": ["Cansaço apenas", "Problema cognitivo que merece avaliação", "Falta de vontade", "Nada"], "a": 1}, {"q": "Tristeza persistente e isolamento podem indicar:", "o": ["Preguiça", "Depressão", "Timidez, sempre", "Normalidade da idade"], "a": 1}, {"q": "Se notar mudança relevante em mais de uma área, o cuidador deve:", "o": ["Resolver sozinho", "Esperar passar", "Buscar o médico da família ou o geriatra", "Tratar com chás"], "a": 2}, {"q": "A avaliação funcional mostra:", "o": ["A idade biológica", "O peso ideal", "A renda", "O quanto o idoso consegue fazer sozinho"], "a": 3}, {"q": "Pedir para repetir frases e evitar ler podem sugerir problemas de:", "o": ["Digestão", "Visão e audição", "Sono apenas", "Memória apenas"], "a": 1}, {"q": "Quais vacinas o e-book cita para ficar em dia?", "o": ["Só catapora", "Apenas tétano", "Gripe, covid e pneumonia", "Nenhuma"], "a": 2}, {"q": "Mudança no controle da bexiga ou do intestino:", "o": ["Não importa", "É sempre normal", "Deve ser escondida", "Deve ser observada e relatada"], "a": 3}], "caso": {"texto": "Dona Zilda, 75 anos, nos últimos dois meses comeu menos, deixou de ir à missa, repete a mesma pergunta várias vezes e está tropeçando nos tapetes. A família diz: 'é da idade'.", "perguntas": ["Quais áreas de alerta aparecem no caso?", "O que você diria à família?", "Que informações levaria ao médico?"]}, "ativ": {"texto": "Monte uma 'Ficha de Observação Semanal' com as 9 áreas do capítulo (marcar ok/atenção) e preencha por 7 dias para um idoso conhecido (ou simule).", "tempo": "45 min"}}, {"t": "Sono e Incontinência: Cuidando com Naturalidade e Sem Constrangimento", "min": 55, "resumo": ["Com a idade o sono fica mais superficial e fragmentado.", "Tipos de incontinência: esforço, urgência, funcional e intestinal.", "Incontinência é questão de saúde e higiene, não 'defeito de caráter'."], "qs": [{"q": "O sono do idoso naturalmente:", "o": ["Dura 12 horas", "Desaparece", "Fica mais superficial e fragmentado", "É igual ao do jovem"], "a": 2}, {"q": "Ajuda a melhorar o sono:", "o": ["Cochilos longos", "Rotina de horários e luz natural durante o dia", "Telas até tarde", "Café à noite"], "a": 1}, {"q": "Incontinência de esforço é a perda de urina:", "o": ["Só à noite", "Só ao dormir", "Ao tossir, espirrar, rir ou fazer esforço", "Por causa de remédios apenas"], "a": 2}, {"q": "Incontinência funcional ocorre quando:", "o": ["A bexiga não funciona", "O idoso quer", "Só há doença de rim", "Há limitação física ou cognitiva que impede chegar ao banheiro a tempo"], "a": 3}, {"q": "Incontinência de urgência é:", "o": ["Perda ao tossir", "Necessidade súbita e intensa de urinar", "Falta de higiene", "Questão de vontade"], "a": 1}, {"q": "Uma estratégia prática de manejo é:", "o": ["Reduzir a água a zero", "Proibir saídas", "Horários regulares de ida ao banheiro", "Ignorar o tema"], "a": 2}, {"q": "Para facilitar o acesso ao banheiro, deve-se:", "o": ["Colocar tapetes escorregadios", "Escurecer o corredor", "Trancar a porta", "Remover tapetes, melhorar a iluminação e instalar barras"], "a": 3}, {"q": "Falar sobre o assunto sem julgamento é importante porque:", "o": ["Não adianta", "A vergonha faz o idoso esconder o problema", "Atrapalha o sono", "É proibido"], "a": 1}, {"q": "Incontinência urinária tem tratamento?", "o": ["Nunca", "Só cirurgia", "Sim, inclusive fisioterapia pélvica", "Só em mulheres jovens"], "a": 2}, {"q": "Tratar a incontinência como 'problema de higiene' e não 'defeito de caráter':", "o": ["Piora a relação", "Não muda nada", "É ofensivo", "Fortalece a confiança entre cuidador e idoso"], "a": 3}], "caso": {"texto": "Seu Raimundo, 84 anos, acorda 4 vezes por noite, cochila 3 horas à tarde e tem 'escapes' de urina que o fazem recusar visitas por vergonha.", "perguntas": ["Que mudanças de rotina você proporia para o sono?", "Como conversar com ele sem constrangimento?", "Que adaptações no ambiente ajudariam?"]}, "ativ": {"texto": "Planeje uma 'rotina da noite' de 6 passos (horário de jantar, luz, banheiro, remédios, ambiente, despedida) e um 'checklist do banheiro seguro'.", "tempo": "40 min"}}, {"t": "Saúde da Mulher Idosa", "min": 55, "resumo": ["Menopausa tardia, osteoporose, incontinência, câncer de mama/útero, saúde mental e sexualidade.", "Prevenção de quedas protege os ossos.", "Mamografia e exames ginecológicos continuam depois dos 60."], "qs": [{"q": "A osteoporose atinge cerca de:", "o": ["1 em cada 100", "Nenhuma mulher", "Só homens", "1 em cada 3 mulheres acima de 60 anos"], "a": 3}, {"q": "Prevenção da osteoporose inclui:", "o": ["Repouso total", "Cálcio, vitamina D, atividade com carga e prevenção de quedas", "Evitar sol sempre", "Beber pouca água"], "a": 1}, {"q": "A menopausa pode se estender até:", "o": ["Os 30 anos", "Os 20 anos", "Os 55–60 anos", "Os 90 anos"], "a": 2}, {"q": "Câncer de mama e de útero são:", "o": ["Raros em idosas", "Problemas só de jovens", "Sem prevenção", "A principal causa de morte por câncer entre mulheres idosas no Brasil"], "a": 3}, {"q": "Mamografia e exames ginecológicos:", "o": ["Não são mais necessários", "Só aos 90", "Devem continuar em dia após os 60", "São proibidos"], "a": 2}, {"q": "Depressão e ansiedade na mulher idosa são:", "o": ["Impossíveis", "Sempre percebidas", "Frequentes e muitas vezes subdiagnosticadas", "Sem tratamento"], "a": 2}, {"q": "A sexualidade na terceira idade:", "o": ["É assunto proibido", "Acaba aos 60", "Continua sendo parte da qualidade de vida e deve ser tratada sem preconceito", "Só importa ao homem"], "a": 2}, {"q": "A incontinência afeta até:", "o": ["Nenhuma", "1%", "Só mulheres jovens", "Metade das mulheres idosas"], "a": 3}, {"q": "Uma fratura por osteoporose:", "o": ["Cura em um dia", "Aumenta a mortalidade e compromete a independência", "É sempre leve", "Não é grave"], "a": 1}, {"q": "O primeiro passo contra a incontinência urinária é:", "o": ["Esconder", "Reduzir líquidos a zero", "Usar só absorvente", "Romper o silêncio e procurar ajuda"], "a": 3}], "caso": {"texto": "Dona Neuza, 69 anos, nunca fez mamografia depois dos 55, deixou de caminhar por medo de cair, evita falar do 'escape' de urina e anda desanimada. A filha diz que 'na idade dela é assim'.", "perguntas": ["Que problemas de saúde específicos da mulher idosa aparecem?", "Que orientações você daria à filha?", "Quais exames e consultas você sugeriria que ela conversasse com o médico?"]}, "ativ": {"texto": "Monte um 'Calendário de Saúde da Mulher Idosa' com consultas, exames e hábitos (cálcio, sol, caminhada) para 6 meses.", "tempo": "40 min"}}, {"t": "Remédios Sem Perigo: o que Todo Cuidador Precisa Saber", "min": 55, "resumo": ["5 certos: paciente, medicamento, dose, via e horário.", "Polifarmácia (5 ou mais remédios) aumenta riscos e a 'cascata de prescrição'.", "Conciliação medicamentosa, organizador semanal, armazenamento e descarte corretos."], "qs": [{"q": "Os '5 certos' incluem:", "o": ["Cor, marca, preço, tamanho e sabor", "Só dose e horário", "Paciente, medicamento, dose, via e horário", "Apenas o paciente"], "a": 2}, {"q": "Polifarmácia é o uso simultâneo de:", "o": ["2 remédios", "3 remédios", "5 ou mais medicamentos", "Apenas vitaminas"], "a": 2}, {"q": "'Cascata de prescrição' acontece quando:", "o": ["Os remédios acabam", "O médico muda de cidade", "Há desconto", "Um remédio novo trata o efeito colateral de outro"], "a": 3}, {"q": "Conciliação medicamentosa é:", "o": ["Comprar remédios em dobro", "Levar à consulta a lista completa e atualizada dos remédios, chás e suplementos", "Misturar comprimidos", "Parar todos os remédios"], "a": 1}, {"q": "O organizador semanal de comprimidos:", "o": ["Aumenta o risco", "É inútil", "Reduz esquecimento e dose duplicada", "Substitui o médico"], "a": 2}, {"q": "Onde guardar remédios?", "o": ["No banheiro úmido", "No carro", "Ao sol", "Em local seco, arejado e longe do sol"], "a": 3}, {"q": "Remédios vencidos devem ser:", "o": ["Jogados na pia", "Descartados em pontos de coleta específicos", "Misturados à comida", "Guardados para sempre"], "a": 1}, {"q": "A pergunta que evita cascatas de prescrição é:", "o": ["'Qual é mais barato?'", "'Posso dobrar a dose?'", "'Posso parar sem avisar?'", "'Este remédio é mesmo necessário ou trata efeito de outro?'"], "a": 3}, {"q": "Com CPF e receita válida, o SUS/Farmácia Popular fornece medicamentos para:", "o": ["Nenhuma doença", "Hipertensão, diabetes e colesterol alto, entre outros", "Só dor de cabeça", "Só vitaminas"], "a": 1}, {"q": "Reação do idoso a uma dose comum de adulto jovem:", "o": ["É sempre idêntica", "Nunca dá efeito", "Dispensa receita", "Pode se acumular e causar tontura, confusão e quedas"], "a": 3}], "caso": {"texto": "Seu Jorge toma 8 remédios. Depois de começar um anti-hipertensivo, passou a tossir; o médico receitou xarope; o xarope o deixou sonolento e ele caiu no banheiro.", "perguntas": ["Que fenômeno do capítulo aparece aqui?", "Que perguntas o cuidador faria ao médico?", "Quais 3 estratégias de segurança você aplicaria?"]}, "ativ": {"texto": "Monte uma 'Lista de Medicamentos' (nome, dose, horário, para que serve, validade) para um idoso e simule o preenchimento de um porta-comprimidos semanal.", "tempo": "45 min"}}, {"t": "Biossegurança e Higiene no Dia a Dia", "min": 55, "resumo": ["Higiene é a primeira linha de defesa: banho, higiene bucal, mãos e superfícies.", "Vacinação em dia e uso correto de máscara e álcool em gel.", "Álcool em gel: friccionar pelo menos 20 segundos."], "qs": [{"q": "Biossegurança é:", "o": ["Uma marca de produto", "Um exame médico", "Um tipo de remédio", "Um conjunto de hábitos que protege contra riscos biológicos, químicos e físicos"], "a": 3}, {"q": "O sistema imunológico do idoso responde:", "o": ["Mais rápido", "De forma mais lenta a infecções", "Igual ao do adulto", "Nunca"], "a": 1}, {"q": "Lavar as mãos é especialmente importante:", "o": ["Só depois de dormir", "Nunca", "Antes das refeições e após o banheiro", "Só em hospitais"], "a": 2}, {"q": "Ao usar álcool em gel, deve-se friccionar por pelo menos:", "o": ["2 segundos", "5 segundos", "20 segundos", "2 minutos"], "a": 2}, {"q": "Ao usar máscara, deve-se:", "o": ["Deixar no queixo", "Cobrir bem nariz e boca e ajustar ao rosto", "Tocar a frente toda hora", "Reutilizar a descartável"], "a": 1}, {"q": "Vacinas citadas como importantes:", "o": ["Nenhuma", "Só sarampo", "Gripe, covid e pneumonia", "Só raiva"], "a": 2}, {"q": "Para reduzir infecções respiratórias, convém:", "o": ["Frequentar festas lotadas", "Evitar aglomerações em períodos de risco", "Ficar sem ventilação", "Dormir pouco"], "a": 1}, {"q": "A higiene bucal do idoso:", "o": ["É dispensável", "Só vale em jovens", "É parte da saúde geral e deve ser regular", "Só aos domingos"], "a": 2}, {"q": "Um ambiente seguro é:", "o": ["Fechado e abafado", "Sem higienização", "Com lixo acumulado", "Ventilado e limpo"], "a": 3}, {"q": "Remédios devem ser guardados:", "o": ["No banheiro", "Ao sol", "Longe de calor e umidade", "Misturados a produtos de limpeza"], "a": 2}], "caso": {"texto": "Na casa de Dona Aurora, 79 anos, ninguém lava as mãos antes das refeições, o álcool em gel está guardado num armário alto e há um surto de gripe no bairro.", "perguntas": ["Que riscos aparecem?", "Que 5 mudanças simples você faria?", "Como orientar a família sem acusar ninguém?"]}, "ativ": {"texto": "Crie um 'Cartaz de Higiene' (passo a passo de lavar as mãos e usar o álcool em gel) e um checklist de biossegurança doméstica para colar na casa.", "tempo": "35 min"}}, {"t": "Alimentação Segura e Nutritiva", "min": 55, "resumo": ["Paladar e olfato diminuem; digestão muda.", "Cálcio, vitamina D e proteínas são essenciais; evite desnutrição e obesidade.", "Segurança: refrigeração, validade, contaminação cruzada, cozimento."], "qs": [{"q": "Com o envelhecimento, paladar e olfato:", "o": ["Ficam mais fortes", "Diminuem, reduzindo o apetite", "Não mudam", "Somem em 1 dia"], "a": 1}, {"q": "Cálcio e vitamina D protegem:", "o": ["Os olhos apenas", "A pele apenas", "Os ossos", "Nada"], "a": 2}, {"q": "Proteínas ajudam a manter:", "o": ["Só o peso", "Só os ossos", "Nada", "A massa muscular"], "a": 3}, {"q": "Para prevenir a desnutrição:", "o": ["Pular refeições", "Refeições menores e mais frequentes e acompanhar o peso", "Só líquidos", "Evitar proteínas"], "a": 1}, {"q": "Um bom sinal de alimentação adequada é:", "o": ["Perda rápida de peso", "Recusar comida", "Peso estável e apetite preservado", "Cansaço constante"], "a": 2}, {"q": "Contaminação cruzada é evitada com:", "o": ["Misturar cru e cozido", "Higiene de mãos, utensílios e superfícies", "Não lavar tábuas", "Cozinhar pouco"], "a": 1}, {"q": "Carnes e ovos devem ser:", "o": ["Crus sempre", "Deixados fora da geladeira", "Servidos mornos", "Bem cozidos"], "a": 3}, {"q": "Para aumentar o apetite de quem come pouco:", "o": ["Servir pratos sem cor", "Forçar a comer", "Adaptar textura e apresentação visual", "Piorar o valor nutricional"], "a": 2}, {"q": "A alimentação afetiva:", "o": ["Não importa", "Valoriza refeições em companhia e pratos com significado", "Deve evitar a família", "Só vale em festas"], "a": 1}, {"q": "Prevenir a obesidade no idoso inclui:", "o": ["Proibir caminhada", "Só açúcar", "Atividade adaptada e controle de porções", "Nenhuma refeição"], "a": 2}], "caso": {"texto": "Dona Isaura, 83 anos, perdeu 4 kg em dois meses, recusa carne dura e come sozinha na frente da TV. O arroz e o feijão vêm requentados da semana anterior.", "perguntas": ["Que riscos nutricionais e de segurança você vê?", "Que adaptações de textura e apresentação você proporia?", "Como tornar a refeição mais afetiva?"]}, "ativ": {"texto": "Monte um cardápio de 3 dias (café, almoço, lanche, jantar) rico em cálcio, vitamina D e proteínas, com texturas adaptadas, e uma lista de compras.", "tempo": "45 min"}}, {"t": "Primeiros Socorros: O que Fazer nos Primeiros Minutos", "min": 55, "resumo": ["Prevenção: tapetes soltos, fios, iluminação e barras de apoio.", "Queda: manter a calma, não mover se houver suspeita de fratura, acionar o SAMU (192).", "Na dúvida entre agir ou ligar, ligue."], "qs": [{"q": "Telefone do SAMU:", "o": ["190", "192", "193", "180"], "a": 1}, {"q": "Após uma queda com suspeita de fratura, deve-se:", "o": ["Levantar a pessoa rapidamente", "Manter calma, não mover e acionar o SAMU", "Dar remédio", "Ignorar"], "a": 1}, {"q": "Na hipoglicemia, com o idoso consciente:", "o": ["Dar insulina extra", "Não fazer nada", "Oferecer algo doce", "Deixar dormir"], "a": 2}, {"q": "Se o idoso estiver inconsciente, na hipoglicemia:", "o": ["Dar suco", "Dar água", "Dar comida", "Não oferecer nada por via oral e acionar o SAMU"], "a": 3}, {"q": "Em sangramentos, aplica-se pressão direta por pelo menos:", "o": ["10 segundos", "1 minuto", "10 minutos", "1 hora"], "a": 2}, {"q": "Se a compressa encharcar:", "o": ["Trocar tirando a primeira", "Adicionar outra por cima, sem remover a primeira", "Parar a pressão", "Lavar a ferida com álcool"], "a": 1}, {"q": "Em um desmaio consciente, mas tonto:", "o": ["Dar café", "Deixar em pé", "Deitar e elevar as pernas", "Dar banho"], "a": 2}, {"q": "Quando ligar para o SAMU?", "o": ["Só em feriados", "Nunca", "Perda de consciência, dor no peito, falta de ar, sangramento que não para", "Só se a família pedir"], "a": 2}, {"q": "Administrar um remédio 'extra' em crise, sem orientação:", "o": ["É sempre correto", "É obrigatório", "Cura tudo", "Pode agravar o quadro"], "a": 3}, {"q": "A regra de ouro é:", "o": ["Esperar para ver", "Agir sempre sozinho", "Na dúvida entre agir ou ligar, ligue", "Evitar o socorro"], "a": 2}], "caso": {"texto": "Às 3h da manhã, Dona Marta ouve um barulho: sua mãe, de 82 anos, caiu a caminho do banheiro, sente dor forte na perna e não consegue se levantar.", "perguntas": ["Quais são os passos, na ordem correta?", "O que NÃO deve ser feito?", "Que informações passar ao SAMU?"]}, "ativ": {"texto": "Monte um 'Cartão de Emergência' (nome, idade, doenças, remédios, alergias, contatos, SAMU 192) e um mapa de riscos de quedas da casa com 5 correções.", "tempo": "45 min"}}, {"t": "Qualidade de Vida e Propósito", "min": 55, "resumo": ["Bem-estar = atividade física, estímulo cognitivo/social, ambiente seguro e propósito.", "Plano pessoal: 1 a 3 metas realistas.", "Celebrar pequenas conquistas."], "qs": [{"q": "Qual item é pilar do bem-estar?", "o": ["Isolamento", "Sedentarismo", "Silêncio", "Atividade física"], "a": 3}, {"q": "O estímulo cognitivo e social inclui:", "o": ["Só TV", "Só sono", "Conversas, jogos, leitura e contato com amigos", "Nada"], "a": 2}, {"q": "Um ambiente seguro permite ao idoso:", "o": ["Ficar parado", "Sentir-se livre para se movimentar", "Evitar a casa", "Temer andar"], "a": 1}, {"q": "Senso de propósito pode vir de:", "o": ["Só da doença", "Do isolamento", "Do medo", "Hobbies, grupos comunitários e voluntariado"], "a": 3}, {"q": "No plano de bem-estar, definem-se:", "o": ["20 metas", "Nenhuma", "1 a 3 metas realistas", "Só metas médicas"], "a": 2}, {"q": "Exemplo de meta realista:", "o": ["Correr uma maratona", "Caminhar 30 minutos, 3 vezes por semana", "Nunca sair", "Parar de comer"], "a": 1}, {"q": "Depois de definir metas, é preciso:", "o": ["Esquecer", "Desistir", "Mudar de casa", "Identificar barreiras e como superá-las"], "a": 3}, {"q": "Celebrar pequenas conquistas:", "o": ["É perda de tempo", "Atrapalha", "Mantém a motivação", "Não funciona"], "a": 2}, {"q": "Qualidade de vida é:", "o": ["Um destino fixo", "Sorte", "Só dinheiro", "Uma construção diária"], "a": 3}, {"q": "Uma refeição compartilhada é:", "o": ["Irrelevante", "Uma escolha que soma ao bem-estar", "Prejudicial", "Proibida"], "a": 1}], "caso": {"texto": "Seu Odair, 74 anos, viúvo, passa os dias na poltrona. Já foi catador de histórias e jogador de dominó, mas 'perdeu a vontade'. Está de bom peso e sem doenças graves.", "perguntas": ["Que pilares do bem-estar estão faltando?", "Que 3 metas realistas você proporia a ele, junto com ele?", "Quais barreiras podem aparecer?"]}, "ativ": {"texto": "Elabore, junto com um idoso (ou simule), um 'Plano Pessoal de Bem-estar' de 1 mês com 3 metas, barreiras, soluções e um dia de revisão e celebração.", "tempo": "40 min"}}, {"t": "Transforme Esse Conhecimento em Profissão", "min": 55, "resumo": ["Mercado em expansão: residências, ILPIs, casas de repouso, hospitais e clínicas.", "Destaque: especializações, currículo, comunicação, ética e atualização.", "Cuide de você: estresse, ergonomia e descanso."], "qs": [{"q": "Um local de trabalho para o cuidador é:", "o": ["Somente aviões", "Só bancos", "ILPIs, casas de repouso, residências e clínicas geriátricas", "Nenhum"], "a": 2}, {"q": "A remuneração, segundo o e-book, depende de:", "o": ["Do signo", "Região, carga horária e regime de contratação", "Só da idade", "De nada"], "a": 1}, {"q": "Para se destacar, o cuidador deve:", "o": ["Esconder certificados", "Evitar aprender", "Ser impontual", "Buscar especializações e manter currículo organizado"], "a": 3}, {"q": "Habilidade tão importante quanto a técnica:", "o": ["Nenhuma", "Velocidade", "Comunicação interpessoal", "Silêncio absoluto"], "a": 2}, {"q": "Ética que valoriza a reputação inclui:", "o": ["Fofoca", "Atrasos", "Sigilo, pontualidade e respeito", "Ignorar a família"], "a": 2}, {"q": "Um diário de cuidados serve para:", "o": ["Esconder informações", "Facilitar o acompanhamento médico e a comunicação com a família", "Substituir o médico", "Nada"], "a": 1}, {"q": "A família do idoso deve ser tratada como:", "o": ["Inimiga", "Parceira, não fiscal", "Inexistente", "Cliente apenas"], "a": 1}, {"q": "Cuidador esgotado:", "o": ["Cuida melhor", "Não precisa de descanso", "Cuida pior; é preciso descanso e hobbies", "Não sente estresse"], "a": 2}, {"q": "A postura ergonômica evita:", "o": ["Chuva", "Febre", "Fome", "Lesões físicas no trabalho"], "a": 3}, {"q": "Diferencia um bom cuidador de um excelente:", "o": ["Gritar", "Fugir", "Ser resolutivo e calmo diante de crises", "Ignorar"], "a": 2}], "caso": {"texto": "Camila, 29 anos, acaba de ser contratada para plantões de 12x36 numa casa de repouso. Está cansada, sem hobby e já pensa em desistir. A família de um residente pede relatórios diários.", "perguntas": ["Que cuidados consigo mesma ela precisa ter?", "Como organizar o diário de cuidados?", "Que atitudes valorizam sua reputação?"]}, "ativ": {"texto": "Monte seu currículo de cuidador (ou um modelo): objetivo, formação (inclua este certificado), cursos, experiência, referências e 3 diferenciais. Escreva também uma mensagem de apresentação de 5 linhas para famílias.", "tempo": "50 min"}}], "final": [{"q": "Envelhecer é:", "o": ["Uma doença", "Um processo natural e gradual", "Um castigo", "Uma escolha"], "a": 1}, {"q": "O Estatuto do Idoso garante atendimento prioritário a partir dos:", "o": ["50 anos", "60 anos", "70 anos", "80 anos"], "a": 1}, {"q": "Infantilizar o idoso é:", "o": ["Um respeito", "Uma forma sutil de desrespeito", "Um tratamento médico", "Uma lei"], "a": 1}, {"q": "ABVD é:", "o": ["Avaliação Básica de Vacinas", "Atividade de Banho e Vestuário", "Atividades Básicas da Vida Diária", "Ação Básica de Visitas"], "a": 2}, {"q": "Depressão no idoso é:", "o": ["Rara", "Comum e muitas vezes subdiagnosticada", "Impossível", "Sempre diagnosticada"], "a": 1}, {"q": "Um modo prático de manejar a incontinência é:", "o": ["Cortar a água", "Esconder o problema", "Horários regulares no banheiro", "Tapar com roupas"], "a": 2}, {"q": "A osteoporose é prevenida com:", "o": ["Repouso total", "Evitar o sol", "Cálcio, vitamina D, atividade com carga e prevenção de quedas", "Álcool"], "a": 2}, {"q": "Os 5 certos incluem:", "o": ["Preço, cor e marca", "Paciente, medicamento, dose, via e horário", "Só horário", "Só dose"], "a": 1}, {"q": "Polifarmácia é o uso de:", "o": ["1 remédio", "2 remédios", "5 ou mais medicamentos", "Só vitaminas"], "a": 2}, {"q": "O álcool em gel deve ser friccionado por pelo menos:", "o": ["2 segundos", "5 segundos", "1 hora", "20 segundos"], "a": 3}, {"q": "Uma boa estratégia de higiene é:", "o": ["Nunca lavar", "Lavar só aos domingos", "Usar a mesma toalha de todos", "Lavar as mãos antes das refeições"], "a": 3}, {"q": "Bom sinal de alimentação adequada:", "o": ["Perda de peso", "Recusa total", "Peso estável e apetite preservado", "Cansaço"], "a": 2}, {"q": "Cálcio e vitamina D protegem:", "o": ["Cabelo", "Unhas apenas", "Ossos", "Nada"], "a": 2}, {"q": "Após queda com suspeita de fratura:", "o": ["Levantar de qualquer jeito", "Dar remédio", "Ignorar", "Não mover e acionar o SAMU (192)"], "a": 3}, {"q": "Hipoglicemia com consciência:", "o": ["Deixar dormir", "Oferecer algo doce", "Dar remédio extra", "Ignorar"], "a": 1}, {"q": "Sangramento: aplicar pressão direta por pelo menos:", "o": ["10 segundos", "1 minuto", "30 segundos", "10 minutos"], "a": 3}, {"q": "O plano de bem-estar tem:", "o": ["20 metas", "Nenhuma", "Só metas médicas", "1 a 3 metas realistas"], "a": 3}, {"q": "Um local de trabalho para cuidadores é:", "o": ["Estádio", "ILPI", "Aeroporto", "Cinema"], "a": 1}, {"q": "Diário de cuidados serve para:", "o": ["Esconder informações", "Nada", "Registro e comunicação com a família e o médico", "Substituir o SAMU"], "a": 2}, {"q": "A regra de ouro das emergências é:", "o": ["Espere", "Tente sozinho", "Ignore", "Na dúvida, ligue"], "a": 3}], "minFinal": 60}, {"id": "beleza", "nome": "Do Caos ao Controle", "curto": "Educação financeira para beleza", "horas": 12, "c1": "#701E54", "c2": "#FF7896", "capa": "capas/beleza.jpg", "modulos": [{"t": "Faturar Não É Lucrar: seu Diagnóstico Financeiro", "min": 55, "resumo": ["A pergunta que importa não é 'quanto entrou?', é 'quanto ficou?'.", "Os 5 pilares da fotografia financeira: receita, despesas do negócio, despesas pessoais, dívidas e reserva.", "É do lucro, e não do faturamento, que saem o seu salário, a reserva e o crescimento."], "qs": [{"q": "Um salão fatura R$ 20.000 e gasta R$ 18.500. Quanto sobra?", "o": ["R$ 1.500", "R$ 20.000", "R$ 18.500", "R$ 38.500"], "a": 0}, {"q": "A pergunta mais importante da gestão financeira é:", "o": ["Quanto ficou?", "Quanto entrou?", "Quantas clientes tenho?", "Quanto o concorrente cobra?"], "a": 0}, {"q": "Quantos são os pilares da fotografia financeira?", "o": ["5", "3", "7", "10"], "a": 0}, {"q": "Qual item NÃO é pilar da fotografia financeira?", "o": ["Número de seguidores", "Receita mensal", "Dívidas", "Reserva financeira"], "a": 0}, {"q": "A 'receita mensal' é:", "o": ["Tudo o que entrou de fato no último mês fechado", "O que a cliente prometeu pagar", "O lucro do mês", "Só o que foi pago no cartão"], "a": 0}, {"q": "Quem fatura R$ 4.000 com custos de R$ 1.700 tem lucro estimado de:", "o": ["R$ 2.300", "R$ 4.000", "R$ 1.700", "R$ 5.700"], "a": 0}, {"q": "É do lucro que saem:", "o": ["O salário, a reserva e o crescimento do negócio", "Só o aluguel", "Só as dívidas", "Nada, o lucro não tem uso"], "a": 0}, {"q": "Faturar muito e lucrar pouco acontece principalmente por:", "o": ["Falta de controle de custos, preços e despesas", "Falta de clientes", "Excesso de reserva", "Pagar o DAS"], "a": 0}, {"q": "O GPS é usado como exemplo porque:", "o": ["Antes de traçar a rota é preciso saber onde você está", "Ajuda a achar clientes", "Mostra o lucro", "Calcula o preço"], "a": 0}, {"q": "Para fazer a fotografia financeira, usa-se os números do:", "o": ["Último mês fechado", "Mês que vem", "Ano passado inteiro", "Dia de hoje apenas"], "a": 0}], "caso": {"texto": "Dona de um salão, a Paula tem a agenda sempre cheia e fatura R$ 9.000 por mês, mas vive sem dinheiro. Ela nunca somou os custos do mês e acha que 'precisa de mais clientes'.", "perguntas": ["Por que 'mais clientes' pode não resolver o problema dela?", "Que informações ela precisa levantar primeiro (os 5 pilares)?", "O que você diria a ela sobre faturamento e lucro?"]}, "ativ": {"texto": "Faça a sua fotografia financeira: anote a receita do último mês fechado, os custos do negócio, as despesas pessoais, o total das dívidas e a reserva atual. Calcule o lucro estimado (receita menos custos profissionais).", "tempo": "45 min"}}, {"t": "Os 7 Erros Financeiros e a Mentalidade da Empresária", "min": 55, "resumo": ["Sete erros se repetem no setor da beleza, como misturar dinheiro e não registrar entradas e saídas.", "Filtro das 3 perguntas antes de comprar: aumenta a receita? Tenho caixa? Se eu esperar 7 dias, ainda vou querer?", "Plano de 90 dias: organizar, corrigir e construir."], "qs": [{"q": "Qual NÃO é um dos 7 erros do capítulo?", "o": ["Ter reserva financeira", "Misturar dinheiro pessoal e profissional", "Precificar copiando concorrentes", "Não registrar entradas e saídas"], "a": 0}, {"q": "O objetivo ao marcar os erros é:", "o": ["Escolher por onde começar, sem se culpar", "Se punir", "Demitir alguém", "Aumentar o preço de tudo"], "a": 0}, {"q": "Por onde atacar primeiro?", "o": ["Pelo erro de maior impacto no seu bolso", "Pelo mais fácil", "Por todos de uma vez", "Pelo menos importante"], "a": 0}, {"q": "Gatilhos emocionais de compra citados são:", "o": ["Comparação, escassez e compensação emocional", "Lucro, caixa e reserva", "Meta, prazo e plano", "Preço, custo e margem"], "a": 0}, {"q": "Uma promoção que 'só vale hoje' usa o gatilho da:", "o": ["Escassez", "Comparação", "Compensação", "Reserva"], "a": 0}, {"q": "Pergunta do filtro das 3 perguntas:", "o": ["Se eu esperar 7 dias, ainda vou querer?", "A cor é bonita?", "A colega comprou?", "É a mais cara?"], "a": 0}, {"q": "Dias 1 a 30 do plano de 90 dias:", "o": ["Organizar", "Corrigir", "Construir", "Descansar"], "a": 0}, {"q": "Dias 61 a 90 do plano de 90 dias:", "o": ["Construir: iniciar reserva e meta concreta", "Organizar contas", "Só comprar equipamentos", "Fechar o negócio"], "a": 0}, {"q": "Uma boa meta é:", "o": ["Específica, como 'R$ 200 por semana x 12 semanas = R$ 2.400'", "Genérica, como 'ganhar mais'", "Sem prazo", "Secreta"], "a": 0}, {"q": "'O que não é medido...'", "o": ["não pode ser melhorado", "melhora sozinho", "não importa", "vira lucro"], "a": 0}], "caso": {"texto": "Renata comprou um kit de produtos em promoção 'só hoje' porque a colega do salão ao lado também comprou. Não tinha o dinheiro em caixa e parcelou no cartão. Duas semanas depois, o kit ainda estava fechado.", "perguntas": ["Quais gatilhos emocionais agiram na compra?", "Como o filtro das 3 perguntas teria ajudado?", "O que ela poderia fazer agora para corrigir?"]}, "ativ": {"texto": "Marque quais dos 7 erros você comete hoje, escolha o de maior impacto e monte seu plano de 90 dias com uma ação concreta para cada período (organizar, corrigir, construir).", "tempo": "45 min"}}, {"t": "Separando o Dinheiro Pessoal do Profissional", "min": 55, "resumo": ["Ver dinheiro na conta não é ter dinheiro disponível: parte pertence ao negócio.", "Passo a passo: contas separadas, pró-labore, dia fixo de pagamento, regras claras e começar hoje.", "Pró-labore = despesas pessoais + 10% a 20% para emergências."], "qs": [{"q": "Pró-labore é:", "o": ["O seu 'salário' retirado do negócio", "Um imposto", "Um tipo de seguro", "O lucro de um serviço"], "a": 0}, {"q": "Despesas pessoais de R$ 2.000 pedem um pró-labore de cerca de:", "o": ["R$ 2.200 a R$ 2.400", "R$ 500", "R$ 2.000 exatos sempre", "R$ 5.000"], "a": 0}, {"q": "A primeira ação do passo a passo é:", "o": ["Abrir contas separadas (pessoal e profissional)", "Contratar sócia", "Aumentar preços", "Fechar o negócio"], "a": 0}, {"q": "Quem atende em casa e usa 20% dela para trabalhar deve considerar:", "o": ["20% da luz, água e internet como despesa do negócio", "Nada como despesa", "100% da luz", "Só o aluguel"], "a": 0}, {"q": "Em meses bons, quem tem renda irregular deve:", "o": ["Guardar na conta profissional para complementar os meses fracos", "Gastar tudo", "Doar o excedente", "Aumentar o pró-labore sem limite"], "a": 0}, {"q": "Numa emergência pessoal, retirar dinheiro do negócio exige:", "o": ["Anotar data, valor e motivo e repor como empréstimo", "Nada, é livre", "Fechar o caixa", "Avisar a clientela"], "a": 0}, {"q": "Erro comum ao separar as finanças:", "o": ["Fazer 'exceçõezinhas' toda semana", "Ter dia fixo de pagamento", "Escrever as regras", "Abrir conta digital"], "a": 0}, {"q": "Um pró-labore alto demais pode:", "o": ["Deixar o negócio sem capital de giro", "Aumentar a reserva", "Reduzir dívidas", "Gerar lucro automático"], "a": 0}, {"q": "Quanto tempo dar, no mínimo, para a nova rotina?", "o": ["90 dias de tentativa honesta", "1 dia", "1 semana", "Não precisa de tempo"], "a": 0}, {"q": "Na sociedade, o lucro é:", "o": ["O que sobra depois dos custos e dos pró-labores", "O faturamento total", "O pró-labore", "A reserva"], "a": 0}], "caso": {"texto": "Marina, manicure, recebeu R$ 900 na semana. Gastou R$ 400 no mercado, R$ 150 em roupas e R$ 100 numa dívida pessoal. Quando foi repor esmaltes (R$ 180) e pagar a luz do espaço (R$ 80), o dinheiro tinha acabado.", "perguntas": ["Qual foi o erro principal da Marina?", "Como ela deveria organizar esse dinheiro na semana seguinte?", "Que regras escritas ela poderia criar?"]}, "ativ": {"texto": "Defina seu pró-labore: some suas despesas pessoais do mês, acrescente de 10% a 20% e escolha o dia fixo de 'pagamento'. Escreva 4 regras de separação do dinheiro e deixe à vista.", "tempo": "40 min"}}, {"t": "Entradas e Saídas: o Fim do “Dinheiro Invisível”", "min": 55, "resumo": ["Dinheiro invisível são os gastos pequenos que ninguém percebe e que somam muito no mês.", "Entradas, despesas fixas, despesas variáveis e investimentos têm tratamentos diferentes.", "Margem de lucro = (receita - despesas) ÷ receita. Três formas de controlar: caderninho, planilha ou aplicativo."], "qs": [{"q": "Dinheiro invisível é:", "o": ["Gastos pequenos que ninguém percebe", "Dinheiro no banco", "Lucro do mês", "Reserva de emergência"], "a": 0}, {"q": "Camila descobriu R$ 340 de gastos invisíveis. Isso era cerca de:", "o": ["10% do faturamento dela", "1% do faturamento", "50% do faturamento", "Nada importante"], "a": 0}, {"q": "Uma entrada só conta quando:", "o": ["O dinheiro entrou de verdade", "A cliente prometeu pagar", "O serviço foi agendado", "O orçamento foi enviado"], "a": 0}, {"q": "Aluguel do espaço e internet são despesas:", "o": ["Fixas", "Variáveis", "Investimentos", "Lucro"], "a": 0}, {"q": "Produtos profissionais e descartáveis são despesas:", "o": ["Variáveis", "Fixas", "Pessoais", "Investimentos"], "a": 0}, {"q": "Curso e equipamento novo são:", "o": ["Investimentos", "Despesas do dia a dia", "Entradas", "Dívidas"], "a": 0}, {"q": "No controle diário, o pró-labore é:", "o": ["Retirada de lucro, anotada separado", "Despesa do dia a dia", "Receita", "Imposto"], "a": 0}, {"q": "Quem faturou R$ 5.000 e gastou R$ 2.000 tem margem de:", "o": ["60%", "40%", "30%", "100%"], "a": 0}, {"q": "A opção de controle recomendada no capítulo é:", "o": ["Planilha, com categorias e resumo mensal", "Só a memória", "Não controlar", "Só o extrato do banco"], "a": 0}, {"q": "O melhor aplicativo de controle é:", "o": ["O que você realmente usa", "O mais caro", "O com mais botões", "O que ninguém usa"], "a": 0}], "caso": {"texto": "Camila, manicure há cinco anos, nunca anotou os pequenos gastos. Ao registrar 30 dias, descobriu R$ 340 de 'pequenas coisas' (estacionamento, lanche, esmalte de reposição) e que o design de sobrancelha de R$ 25 custava R$ 18.", "perguntas": ["Que tipo de gasto é o 'dinheiro invisível'?", "O que o lucro de R$ 7 por serviço revela?", "Que ações ela deveria tomar a partir dessa descoberta?"]}, "ativ": {"texto": "Registre entradas e saídas por 7 dias seguidos (no caderninho, planilha ou app), separando fixas, variáveis e investimentos. No fim, some e calcule a margem de lucro da semana.", "tempo": "50 min"}}, {"t": "Sua Rotina Financeira: Diária, Semanal e Mensal", "min": 55, "resumo": ["Todo dia fechar o caixa (5 a 10 min); toda semana revisar e planejar (15 a 20 min); todo mês fechar as contas (30 a 40 min).", "Escolha dia e horário fixos para virar ritual.", "Monte a rotina em 5 passos e comprometa-se por escrito por 90 dias."], "qs": [{"q": "A rotina diária consiste em:", "o": ["Fechar o caixa e guardar comprovantes", "Só pagar contas", "Fazer o balanço anual", "Contratar equipe"], "a": 0}, {"q": "A rotina diária leva em média:", "o": ["5 a 10 minutos", "2 horas", "1 minuto", "1 dia"], "a": 0}, {"q": "A rotina semanal leva em média:", "o": ["15 a 20 minutos", "5 minutos", "3 horas", "1 minuto"], "a": 0}, {"q": "A rotina mensal leva em média:", "o": ["30 a 40 minutos", "5 minutos", "1 dia inteiro", "10 segundos"], "a": 0}, {"q": "Na rotina semanal você deve:", "o": ["Revisar a semana, somar entradas e saídas e planejar a próxima", "Só descansar", "Ignorar o saldo", "Cortar todos os gastos"], "a": 0}, {"q": "Na rotina mensal você calcula:", "o": ["Margem de lucro, despesa por categoria e comparação com o mês anterior", "Só o número de clientes", "O preço do concorrente", "Nada"], "a": 0}, {"q": "Um alarme diário às 19h serve para:", "o": ["Transformar o fechamento do caixa em hábito", "Acordar a cliente", "Marcar horário de almoço", "Pagar o DAS"], "a": 0}, {"q": "Para a rotina virar ritual, o ideal é:", "o": ["Escolher dia e horário fixos", "Mudar sempre de dia", "Fazer só quando lembrar", "Delegar a outra pessoa"], "a": 0}, {"q": "Datas como Dia das Mães e Natal entram no:", "o": ["Planejamento do próximo mês", "Esquecimento", "Imposto anual", "Cadastro de clientes"], "a": 0}, {"q": "Quanto tempo se comprometer a seguir a rotina?", "o": ["Pelo menos 90 dias", "1 dia", "Até a primeira dificuldade", "Só no verão"], "a": 0}], "caso": {"texto": "Juliana é maquiadora e sempre diz que 'não tem tempo para planilha'. Atende de segunda a sábado, só olha o saldo quando falta dinheiro e nunca sabe quanto fatura por semana.", "perguntas": ["Quais rotinas (diária, semanal, mensal) fariam falta no dia a dia dela?", "Como ela poderia encaixar isso na agenda sem perder atendimentos?", "O que ela ganharia depois de 90 dias de rotina?"]}, "ativ": {"texto": "Monte sua rotina financeira em 5 passos: mapeie sua semana, escolha horários, crie alarmes, prepare o ambiente (caderno/celular e pasta de comprovantes) e escreva seu compromisso de 90 dias.", "tempo": "40 min"}}, {"t": "Contas a Receber e a Pagar: Cobrar Sem Culpa, Pagar Sem Juros", "min": 55, "resumo": ["Políticas claras (pagamento, agendamento, cancelamento) evitam a maior parte dos problemas.", "Registre cada valor pendente: quem deve, quanto, desde quando e situação.", "Contas a pagar: calendário de vencimentos, prioridade, negociar antes de atrasar e reserva de 1 mês de contas fixas."], "qs": [{"q": "Políticas do negócio são:", "o": ["As regras comunicadas antes de qualquer problema", "Leis do governo", "Metas de vendas", "Contas a pagar"], "a": 0}, {"q": "Para clientes novas, o recomendado é:", "o": ["Pagamento no dia do serviço", "Pagar depois", "Parcelar sem entrada", "Fiado por 3 meses"], "a": 0}, {"q": "Pagamento posterior (se aceito) deve valer:", "o": ["Só para clientes com histórico e prazo máximo definido", "Para todas", "Sem prazo", "Só para amigas"], "a": 0}, {"q": "Uma boa política de cancelamento prevê:", "o": ["Confirmação 24h antes e taxa para falta sem aviso", "Nenhuma regra", "Multa para a profissional", "Só avisos por rede social"], "a": 0}, {"q": "No registro de contas a receber, anota-se:", "o": ["Nome, telefone, serviço, valor, data combinada e situação", "Só o valor", "Só o nome", "Só a data"], "a": 0}, {"q": "A situação de uma conta a receber pode ser:", "o": ["Pendente, paga ou atrasada", "Bonita, feia ou média", "Cara ou barata", "Nova ou velha"], "a": 0}, {"q": "Para evitar juros nas contas a pagar:", "o": ["Mapear vencimentos em um calendário", "Pagar sempre atrasado", "Ignorar boletos", "Pedir emprestado todo mês"], "a": 0}, {"q": "Em um mês apertado, deve-se priorizar:", "o": ["O que gera maior prejuízo se atrasar", "O que é mais barato", "O que é mais bonito", "Nada"], "a": 0}, {"q": "É melhor negociar prazos:", "o": ["Antes de atrasar", "Depois de atrasar", "Nunca", "Só no fim do ano"], "a": 0}, {"q": "A reserva para contas fixas deve equivaler a:", "o": ["1 mês de contas fixas", "1 dia", "10 anos", "Nenhum valor"], "a": 0}], "caso": {"texto": "A Priscila tem medo de cobrar e perder cliente. Há três clientes que devem a ela R$ 150, R$ 90 e R$ 260 há mais de 2 meses. Ela não anotou nada e já atendeu uma delas de novo 'sem tocar no assunto'.", "perguntas": ["Que políticas ela deveria ter criado antes?", "Como cobrar de forma educada e firme?", "O que passa a registrar para nunca esquecer?"]}, "ativ": {"texto": "Escreva suas políticas de pagamento e cancelamento (em 6 linhas) e uma mensagem educada de cobrança para enviar por WhatsApp. Monte uma lista de contas a receber e um calendário de contas a pagar.", "tempo": "50 min"}}, {"t": "Precificação Estratégica e Redução de Custos", "min": 55, "resumo": ["Preço justo = custo direto + custo indireto + valor da sua hora + margem de lucro (20% a 40%).", "Reajuste com 30 dias de antecedência, por escrito, sem se justificar demais.", "5 vazamentos: estoque parado, desperdício, fornecedor sem comparação, custos fixos inchados e retrabalho."], "qs": [{"q": "Custo direto é:", "o": ["Tudo o que é consumido no atendimento (produtos, descartáveis)", "Aluguel", "Pró-labore", "Imposto"], "a": 0}, {"q": "Custo indireto proporcional inclui:", "o": ["Aluguel, luz, água, internet e taxas", "Só esmalte", "Só o lanche", "Nenhum gasto"], "a": 0}, {"q": "O valor da sua hora calcula-se:", "o": ["Quanto quer ganhar por mês ÷ horas realmente trabalhadas", "Pelo preço da colega", "Por sorteio", "Pelo faturamento"], "a": 0}, {"q": "A margem de lucro recomendada é de:", "o": ["20% a 40% sobre o custo total", "1%", "200%", "Nenhuma"], "a": 0}, {"q": "A fórmula do preço justo soma:", "o": ["Custo direto + indireto + valor da hora + margem de lucro", "Só o custo direto", "Só a margem", "O preço do concorrente"], "a": 0}, {"q": "Ao reajustar preços, o ideal é avisar com:", "o": ["30 dias de antecedência", "No dia", "1 hora", "Não avisar"], "a": 0}, {"q": "Qual NÃO é um dos 5 vazamentos?", "o": ["Reajustar o preço com carinho", "Estoque parado", "Desperdício por falta de medida", "Retrabalho"], "a": 0}, {"q": "Para reduzir custos de fornecedor, deve-se:", "o": ["Cotar com três fornecedores a cada trimestre", "Comprar sempre do mesmo", "Comprar o mais caro", "Nunca comparar"], "a": 0}, {"q": "Cortar custo significa:", "o": ["Cortar o desperdício, nunca o valor entregue", "Comprar produto ruim", "Atender mais rápido sem cuidado", "Cancelar a biossegurança"], "a": 0}, {"q": "A Simone cobrava R$ 40 e cada atendimento custava mais de R$ 22. Faltava:", "o": ["Contar o valor da própria hora", "Mais clientes", "Mais esmalte", "Menos agenda"], "a": 0}], "caso": {"texto": "A Simone, manicure, cobra R$ 40 pela manicure completa e atende cerca de 25 clientes por semana. Ao somar esmaltes (R$ 3,50), descartáveis (R$ 2,00), luz, água e aluguel, cada atendimento custa mais de R$ 22, sem contar a hora dela.", "perguntas": ["O que sobra de fato para a Simone em cada serviço?", "Como calcular o preço justo para ela?", "Que vazamentos de custo ela deveria procurar?"]}, "ativ": {"texto": "Calcule o preço justo dos seus 3 serviços mais vendidos (custo direto, indireto, valor da hora e margem) e identifique pelo menos 3 vazamentos de custo no seu negócio.", "tempo": "60 min"}}, {"t": "Metas, Reserva de Emergência e Investimento no Negócio", "min": 55, "resumo": ["Meta boa é SMART: específica, mensurável, atingível, relevante e com prazo.", "Reserva de emergência: 6 meses de custos essenciais; comece com a mini-meta de R$ 1.000 e guarde de 5% a 10% do que entra.", "Payback = custo ÷ retorno mensal: até 6 meses é excelente."], "qs": [{"q": "SMART significa meta:", "o": ["Específica, mensurável, atingível, relevante e temporal", "Rápida, simples, barata e fácil", "Só com sonho", "Sem prazo"], "a": 0}, {"q": "'Ganhar mais' é:", "o": ["Um desejo, não uma meta", "Uma meta perfeita", "Uma meta SMART", "Um plano de 90 dias"], "a": 0}, {"q": "Uma meta temporal tem:", "o": ["Prazo definido", "Nenhum número", "Só emoção", "Valor aleatório"], "a": 0}, {"q": "A reserva ideal para autônomas é de:", "o": ["6 meses dos custos essenciais", "1 dia", "R$ 10", "Nenhuma"], "a": 0}, {"q": "Quem tem custos essenciais de R$ 3.000 por mês precisa de reserva de:", "o": ["R$ 18.000", "R$ 3.000", "R$ 6.000", "R$ 30.000"], "a": 0}, {"q": "A primeira mini-meta da reserva é:", "o": ["R$ 1.000", "R$ 100.000", "R$ 1", "Nenhuma"], "a": 0}, {"q": "Quanto separar da receita para a reserva?", "o": ["5% a 10% no mesmo dia", "0%", "90%", "Só o que sobrar"], "a": 0}, {"q": "A reserva de emergência deve ficar em:", "o": ["Conta ou investimento com liquidez diária e baixo risco", "Ações de alto risco", "Dinheiro escondido", "Compra de estoque"], "a": 0}, {"q": "O payback é:", "o": ["O custo dividido pelo retorno mensal", "O lucro anual", "O preço do serviço", "A reserva"], "a": 0}, {"q": "Um curso de R$ 1.200 que gera R$ 600 por mês tem payback de:", "o": ["2 meses", "12 meses", "20 meses", "Nunca se paga"], "a": 0}], "caso": {"texto": "Daniela, esteticista, quer investir R$ 1.200 em um curso de alongamento de cílios. Ela acredita que conseguirá 4 clientes por mês pagando R$ 150 cada. Ela não tem reserva de emergência.", "perguntas": ["Qual é o payback do investimento dela?", "Faria sentido formar uma reserva antes ou depois? Por quê?", "Como transformar o desejo de 'ganhar mais' em uma meta SMART?"]}, "ativ": {"texto": "Escreva uma meta SMART para os próximos 6 meses, calcule o tamanho da sua reserva de emergência (6 meses de custos essenciais) e monte um plano de 12 meses com uma grande ação por trimestre.", "tempo": "55 min"}}, {"t": "Enxergando o Futuro: Fluxo de Caixa e Lucratividade por Serviço", "min": 55, "resumo": ["Fluxo de caixa real olha para trás; o projetado olha para a frente.", "Projeção de 3 a 6 meses com cenários: realista, otimista (+20%) e pessimista (-20%).", "Classifique serviços: carro-chefe, joia escondida, armadilha e peso morto."], "qs": [{"q": "O fluxo de caixa projetado:", "o": ["Olha para a frente, para o que vai acontecer", "Olha só para trás", "É igual ao real", "Não serve para nada"], "a": 0}, {"q": "A projeção financeira evita:", "o": ["Ficar sem dinheiro para pagar o fornecedor no dia 15", "Cobrar a cliente", "Pagar o DAS", "Fazer metas"], "a": 0}, {"q": "Para prever receitas, usa-se:", "o": ["A média dos últimos 3 a 6 meses e a sazonalidade", "Só a esperança", "O mês de maior sorte", "O preço da concorrência"], "a": 0}, {"q": "Despesas variáveis são calculadas como:", "o": ["Percentual do faturamento", "Valor fixo sempre", "Zero", "Aluguel"], "a": 0}, {"q": "Os três cenários da projeção são:", "o": ["Realista, otimista (+20%) e pessimista (-20%)", "Bom, ruim e médio", "Só o otimista", "Só o pessimista"], "a": 0}, {"q": "Um 'mês de atenção' é aquele que fica:", "o": ["Negativo no cenário pessimista", "Muito positivo", "Sem clientes", "Com feriado"], "a": 0}, {"q": "Serviço de alto lucro e alta demanda é:", "o": ["Carro-chefe", "Armadilha", "Peso morto", "Joia escondida"], "a": 0}, {"q": "Alta demanda e baixo lucro é:", "o": ["Armadilha: reajuste o preço ou reduza o custo", "Carro-chefe", "Joia escondida", "Peso morto"], "a": 0}, {"q": "Alto lucro com baixa demanda é:", "o": ["Joia escondida: divulgue e crie combos", "Armadilha", "Peso morto", "Carro-chefe"], "a": 0}, {"q": "Margem do serviço = ", "o": ["(preço - custo total) ÷ preço", "Preço ÷ 2", "Custo + 10", "Só o preço"], "a": 0}], "caso": {"texto": "Hoje é 1º de outubro e a Letícia tem R$ 3.200 na conta. Ela acha que 'está bem'. Mas sabe que novembro costuma cair para R$ 2.800 em receita e que janeiro é fraco (cerca de R$ 1.500).", "perguntas": ["O que uma projeção mostraria sobre janeiro?", "O que ela poderia fazer nos meses bons para atravessar janeiro?", "Que cenários ela deveria montar?"]}, "ativ": {"texto": "Monte sua projeção de caixa de 3 meses (receitas, despesas fixas, variáveis e saldo) nos três cenários e calcule a margem dos seus serviços para classificá-los (carro-chefe, joia escondida, armadilha, peso morto).", "tempo": "60 min"}}, {"t": "Crescendo Sem Se Perder: Ticket Médio, Equipe e Marca", "min": 55, "resumo": ["Ticket médio = faturamento ÷ número de atendimentos; subir R$ 10 em 100 atendimentos rende R$ 1.000.", "Contratar ou terceirizar: CLT, comissão (30% a 50%) ou aluguel de cadeira; Lei do Salão-Parceiro (13.352/2016).", "Marca pessoal e visão de 3 anos."], "qs": [{"q": "Ticket médio é:", "o": ["Faturamento ÷ número de atendimentos", "O preço mais alto", "O lucro", "A reserva"], "a": 0}, {"q": "Subir R$ 10 no ticket de 100 atendimentos rende:", "o": ["R$ 1.000 a mais", "R$ 10", "R$ 100", "Nada"], "a": 0}, {"q": "Upsell e cross-sell são:", "o": ["Oferecer o complemento certo na hora certa", "Empurrar produtos que a cliente não precisa", "Baixar o preço", "Cancelar serviços"], "a": 0}, {"q": "A regra de ouro da oferta é:", "o": ["Fazer sentido para a cliente", "Vender a qualquer custo", "Vender só o mais caro", "Não oferecer nada"], "a": 0}, {"q": "Pacotes e combos geram:", "o": ["Fidelidade, dinheiro antecipado e agenda previsível", "Só prejuízo", "Reclamação", "Menos clientes"], "a": 0}, {"q": "Sinal de que pode ser hora de contratar:", "o": ["Agenda cheia por mais de 3 meses seguidos e caixa saudável", "Agenda vazia", "Dívidas altas", "Nenhum cliente"], "a": 0}, {"q": "Na comissão, a profissional recebe:", "o": ["Um percentual do que produz (30% a 50%)", "Salário fixo mais encargos", "Valor fixo pelo espaço", "Nada"], "a": 0}, {"q": "No aluguel de cadeira, a profissional:", "o": ["Paga um valor fixo pelo espaço", "Recebe salário", "Tem 13º", "Não paga nada"], "a": 0}, {"q": "A Lei do Salão-Parceiro é a Lei nº:", "o": ["13.352/2016", "10.741/2003", "8.080/1990", "12.345/2010"], "a": 0}, {"q": "A receita nova gerada por uma contratada deve:", "o": ["Superar o custo total dela, com folga", "Ser igual a zero", "Ser menor que o custo", "Não importar"], "a": 0}], "caso": {"texto": "A Carla está há 4 meses com a agenda lotada e recusando clientes. Tem reserva de 3 meses. Quer contratar uma manicure, mas não sabe se é melhor CLT, comissão ou aluguel de cadeira.", "perguntas": ["Os sinais de que é hora de crescer estão presentes? Quais?", "Qual modelo envolve menos risco no começo e por quê?", "Como saber se a contratação 'se paga'?"]}, "ativ": {"texto": "Simule, com seus números, os três modelos de contratação (CLT, comissão e aluguel de cadeira). Dê nota de 0 a 10 à sua marca pessoal em 6 itens e escreva sua visão de 3 anos.", "tempo": "60 min"}}, {"t": "Formalização e Tributação: MEI, DAS e Obrigações em Dia", "min": 55, "resumo": ["Formalizar é proteção e acesso: INSS, crédito melhor, nota fiscal e aposentadoria.", "MEI: abertura gratuita online; obrigações são DAS mensal (vence dia 20), DASN-SIMEI anual e acompanhar o limite.", "Passou do teto do MEI? Procure um contador e migre para ME no Simples Nacional."], "qs": [{"q": "A abertura do MEI é:", "o": ["Gratuita e online, no Portal do Empreendedor", "Cobrada em cartório", "Só presencial", "Impossível"], "a": 0}, {"q": "As 3 obrigações do MEI são:", "o": ["DAS mensal, DASN-SIMEI anual e acompanhar o limite", "Só abrir o CNPJ", "Só pagar o aluguel", "Nenhuma"], "a": 0}, {"q": "O DAS vence todo dia:", "o": ["20", "5", "30", "1º"], "a": 0}, {"q": "O DAS já inclui:", "o": ["O INSS (aposentadoria e benefícios)", "A reserva", "O aluguel", "A luz"], "a": 0}, {"q": "Quem contribui como MEI tem direito a:", "o": ["Benefício por incapacidade, salário-maternidade e aposentadoria", "Nada", "Só nota fiscal", "Só crédito"], "a": 0}, {"q": "A informalidade deixa a profissional sem:", "o": ["Proteção previdenciária e crédito bom", "Clientes", "Estoque", "Agenda"], "a": 0}, {"q": "Quem não tem CNPJ costuma recorrer a:", "o": ["Cheque especial e rotativo do cartão (juros mais caros)", "Crédito barato", "Isenção de juros", "Doações"], "a": 0}, {"q": "A Lei nº 12.592/2012 reconhece:", "o": ["O exercício profissional de manicure, cabeleireira, esteticista e outras", "Só barbeiros", "O MEI", "A reserva"], "a": 0}, {"q": "Atrasos longos no DAS podem:", "o": ["Cancelar o CNPJ e fazer perder benefícios do INSS", "Gerar bônus", "Aumentar o limite", "Não ter efeito"], "a": 0}, {"q": "Quando o negócio passa do teto do MEI:", "o": ["Entra como ME no Simples Nacional, sinal de sucesso", "Fecha o negócio", "Perde os clientes", "Vira informal"], "a": 0}], "caso": {"texto": "A Roberta trabalha há 6 anos como manicure, sem CNPJ. Quebrou o pulso e ficou 3 meses sem atender, sem renda e sem benefício. Condomínios já lhe pediram nota fiscal e ela perdeu os contratos.", "perguntas": ["Que riscos a informalidade trouxe para ela?", "Quais vantagens o MEI teria dado?", "Que hábitos ajudam a manter o MEI em dia?"]}, "ativ": {"texto": "Faça o checklist de formalização: confirme se tem CNPJ, configure lembrete ou débito automático do DAS, crie uma rotina mensal de registrar faturamento e marque no calendário o envio da DASN-SIMEI.", "tempo": "40 min"}}, {"t": "Proteção, Aposentadoria e Patrimônio", "min": 55, "resumo": ["Proteção em 3 camadas: reserva de emergência, INSS em dia e seguros (equipamentos, responsabilidade civil e vida/invalidez).", "Aposentadoria tem dois pilares: INSS via DAS e complemento próprio investido no longo prazo.", "Patrimônio líquido = tudo o que você tem menos tudo o que você deve."], "qs": [{"q": "A gestão de risco tem os passos:", "o": ["Identificar, medir e proteger", "Gastar, esquecer e repetir", "Vender, comprar e cobrar", "Só proteger"], "a": 0}, {"q": "A primeira camada de proteção é:", "o": ["A reserva de emergência", "O seguro de vida", "O estoque", "O aluguel"], "a": 0}, {"q": "O seguro de responsabilidade civil profissional cobre:", "o": ["Reação alérgica e queimadura em clientes", "O aluguel", "A luz", "O lucro"], "a": 0}, {"q": "Proteger-se priorizando:", "o": ["Os riscos de maior impacto", "Só os mais prováveis", "Nenhum risco", "Os mais baratos"], "a": 0}, {"q": "Os dois pilares da aposentadoria são:", "o": ["INSS via DAS e complemento próprio investido", "Só o INSS", "Só a reserva", "Sorte e fé"], "a": 0}, {"q": "Quem começa a guardar aos 30 anos, comparado a quem começa aos 45:", "o": ["Precisa guardar muito menos por mês para chegar ao mesmo valor", "Precisa guardar mais", "Tanto faz", "Não consegue"], "a": 0}, {"q": "R$ 100 por mês começando hoje valem:", "o": ["Mais do que R$ 500 'quando der'", "Menos que nada", "O mesmo que R$ 500 depois", "Nada"], "a": 0}, {"q": "Patrimônio líquido é:", "o": ["Tudo o que tem (bens, reserva, investimentos) menos o que deve", "Só o que deve", "O faturamento", "O lucro do mês"], "a": 0}, {"q": "Ordem sugerida para investir:", "o": ["Reserva completa, depois investimentos conservadores, depois diversificação", "Direto no mais arriscado", "Só em promessas de ganho fácil", "Não investir"], "a": 0}, {"q": "Diante de uma promessa de ganho fácil e rápido, deve-se:", "o": ["Desconfiar", "Investir tudo", "Emprestar dinheiro", "Divulgar para amigas"], "a": 0}], "caso": {"texto": "Tatiana é cabeleireira, tem 34 anos, paga o DAS em dia e nunca pensou em seguro nem em aposentadoria complementar. Seu secador e chapinhas valem R$ 8.000 e ela já sofreu um furto no ano passado.", "perguntas": ["Quais camadas de proteção ela já tem e quais faltam?", "Que riscos deveria priorizar?", "Como montar um plano simples de aposentadoria complementar?"]}, "ativ": {"texto": "Monte seu Mapa de Proteção (risco, impacto e proteção escolhida), calcule o aporte mensal para a aposentadoria desejada e faça seu primeiro inventário de patrimônio (bens + reserva + investimentos - dívidas).", "tempo": "60 min"}}], "final": [{"q": "A pergunta que mais importa na gestão financeira é:", "o": ["Quanto ficou?", "Quanto entrou?", "Quanto gastei no mercado?", "Quanto a concorrente cobra?"], "a": 0}, {"q": "Dos 5 pilares da fotografia financeira, qual NÃO faz parte?", "o": ["Número de seguidores", "Receita mensal", "Dívidas", "Reserva financeira"], "a": 0}, {"q": "O filtro das 3 perguntas inclui:", "o": ["Se eu esperar 7 dias, ainda vou querer?", "A colega comprou?", "É o mais caro?", "Está na moda?"], "a": 0}, {"q": "Pró-labore é:", "o": ["O seu 'salário' retirado do negócio", "Um imposto", "Um seguro", "O custo do aluguel"], "a": 0}, {"q": "O 'dinheiro invisível' representa:", "o": ["Pequenos gastos que somam muito no mês", "O saldo no banco", "A reserva", "O lucro"], "a": 0}, {"q": "Despesa fixa é:", "o": ["Aluguel do espaço", "Produtos usados no serviço", "Curso novo", "Comissão"], "a": 0}, {"q": "O fechamento diário do caixa leva em torno de:", "o": ["5 a 10 minutos", "2 horas", "1 dia", "30 segundos"], "a": 0}, {"q": "Política de pagamento para clientes novas:", "o": ["Pagamento no dia do serviço", "Fiado", "Pagar em 6 meses", "Sem regra"], "a": 0}, {"q": "Preço justo é:", "o": ["Custo direto + indireto + valor da hora + margem de lucro", "O preço da vizinha", "O que a cliente aceita", "O menor possível"], "a": 0}, {"q": "Margem de lucro recomendada sobre o custo total:", "o": ["20% a 40%", "0%", "500%", "1%"], "a": 0}, {"q": "Meta SMART é:", "o": ["Específica, mensurável, atingível, relevante e temporal", "Rápida e fácil", "Sem prazo", "Só de desejo"], "a": 0}, {"q": "Reserva de emergência ideal:", "o": ["6 meses de custos essenciais", "1 dia", "R$ 50", "Não precisa"], "a": 0}, {"q": "Payback é:", "o": ["Custo ÷ retorno mensal", "O lucro anual", "O preço do serviço", "A margem"], "a": 0}, {"q": "O cenário pessimista da projeção é:", "o": ["-20%", "+20%", "0%", "+100%"], "a": 0}, {"q": "Serviço com alta demanda e baixo lucro é:", "o": ["Armadilha", "Carro-chefe", "Joia escondida", "Peso morto"], "a": 0}, {"q": "Ticket médio é:", "o": ["Faturamento ÷ número de atendimentos", "O preço mais caro", "O lucro", "A reserva"], "a": 0}, {"q": "O DAS do MEI vence todo dia:", "o": ["20", "5", "30", "1º"], "a": 0}, {"q": "As duas obrigações anuais e mensais do MEI incluem:", "o": ["DAS mensal e DASN-SIMEI anual", "Só abrir o CNPJ", "Só o aluguel", "Nenhuma"], "a": 0}, {"q": "A primeira camada de proteção é:", "o": ["A reserva de emergência", "O seguro de vida", "O estoque", "O aluguel"], "a": 0}, {"q": "Patrimônio líquido é:", "o": ["O que você tem menos o que você deve", "Só o que você deve", "O faturamento", "O lucro do mês"], "a": 0}], "minFinal": 60}];
